$('a[rel=modal]').on('click', function(evt){
$('div.modal-body').html('');
   evt.preventDefault();
   var modal = $('#modal').modal();
   modal
       .find('.modal-body')
       .load($(this).attr('href'), function (responseText, textStatus){
           if (textStatus === 'error'){
           	var msgError = '<h2>Contenido no encontrado</h2><br>';
           	msgError += '<div role="alert" class="alert alert-danger">';
           	msgError += '<span class="glyphicon glyphicon-warning-sign" aria-hidden="true" style="font-size:24px; margin-right:10px;"></span>';
           	msgError += 'No se ha encontrado contenido relacionado a esta publicaci&oacute;n.';
           	msgError += '</div>';
           	$('div.modal-body').html(msgError);
           }
           if (textStatus === 'success' || textStatus === 'notmodified'){
               modal.show();
           }            
    });
});


